<template><div class="knowledge-source-list"><button v-for="source in sources" :key="`${source.reference_id}-${source.chunk_id}`" type="button" :aria-label="t('components.knowledgeSources.open', { reference: source.reference_id, name: source.document_name, locator: normalizedLocator(source.locator_label) })" @click="$emit('open',source)"><span>[{{ source.reference_id }}]</span><strong>{{ source.document_name }}</strong><small>{{ source.locator_label }} · {{ t(source.retrieval_mode==='hybrid'?'components.knowledgeSources.hybrid':'components.knowledgeSources.keyword') }}</small></button></div></template>
<script setup lang="ts">import type{KnowledgeSource}from '@/api';import{useI18n}from'vue-i18n';const{t}=useI18n();defineProps<{sources:KnowledgeSource[]}>();defineEmits<{(event:'open',source:KnowledgeSource):void}>();const pagePrefix=String.fromCodePoint(0x7b2c);const pageSuffix=String.fromCodePoint(0x9875);const pagePattern=new RegExp(`${pagePrefix}\\s*(\\d+)\\s*${pageSuffix}`,'u');const normalizedLocator=(value:string)=>value.replace(pagePattern,`${pagePrefix}$1${pageSuffix}`)</script>
<style scoped lang="scss">.knowledge-source-list{display:flex;flex-wrap:wrap;gap:7px}.knowledge-source-list button{display:grid;grid-template-columns:auto 1fr;gap:2px 7px;max-width:280px;padding:8px 10px;color:#6d6258;text-align:left;background:#fbf7ef;border:1px solid #e4d9ca;border-radius:10px;cursor:pointer}.knowledge-source-list span{grid-row:1/3;color:#6c9696;font-size:9px}.knowledge-source-list strong{overflow:hidden;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.knowledge-source-list small{color:#9c8e80;font-size:8px}</style>
